{
  "items": [
    {
      "title": "World Bank – World Development Indicators: Germany",
      "url_or_doi": "https://data.worldbank.org/country/germany",
      "justification": "Provides historical economic and development indicators for Germany, including GDP growth, GDP per capita, unemployment, inflation, investment, trade, and income distribution. Data covering 2010–2019 can be used to examine Germany's economic development, structural changes, and performance following the global financial crisis. Particularly useful for comparing Germany with other European economies."
    },
    {
      "title": "German Federal Statistical Office (Destatis) – National Accounts and Domestic Product",
      "url_or_doi": "https://www.destatis.de/EN/Themes/Economy/National-Accounts-Domestic-Product/_node.html",
      "justification": "Official German government statistics covering GDP, gross value added, national income, investment, consumption, and economic activity by sector. Historical data from 2010–2019 allow researchers to investigate Germany's economic structure, industrial development, and economic growth during the decade. Particularly valuable for examining the importance of manufacturing, services, and domestic demand."
    },
    {
      "title": "Destatis – Quarterly National Accounts: Gross Domestic Product and Gross Value Added",
      "url_or_doi": "https://data.europa.eu/data/datasets/https%3A-genesis.destatis.de-genesisws-downloads-00-tables-81000-0002_00?locale=en",
      "justification": "Provides official quarterly German GDP and gross value added statistics, including nominal and inflation-adjusted measures. The dataset is suitable for analyzing quarterly economic fluctuations throughout 2010–2019, identifying periods of expansion and slowdown, and examining changes in economic output. Its quarterly frequency supports detailed time-series analysis."
    },
    {
      "title": "German Socio-Economic Panel (SOEP-Core), 1984–2019 – International Edition",
      "url_or_doi": "https://doi.org/10.5684/soep.core.v36i",
      "justification": "A longitudinal household survey conducted by the German Institute for Economic Research (DIW Berlin). Includes detailed information on household income, employment, education, social mobility, and economic well-being. Its coverage of the entire 2010–2019 period makes it particularly valuable for examining how Germany's economic development affected households, labor markets, income inequality, and living standards. Research data access may require registration and an agreement."
    },
    {
      "title": "German Socio-Economic Panel (SOEP-Core), 1984–2017 – Version 34",
      "url_or_doi": "https://doi.org/10.5684/soep.v34",
      "justification": "Provides longitudinal microdata on Germany's population, including employment conditions, earnings, household finances, education, and socioeconomic mobility. The 2010–2017 observations are useful for studying changes in economic inequality, labor market participation, and social development during the 2010s. Particularly suitable for research examining the relationship between Germany's social market economy and individual economic outcomes."
    },
    {
      "title": "World Bank – World Development Indicators DataBank",
      "url_or_doi": "https://databank.worldbank.org/Germany/id/e9160ab",
      "justification": "An interactive statistical database providing access to historical development indicators for Germany. Researchers can select the 2010–2019 period and examine economic growth, investment, international trade, productivity-related indicators, employment, infrastructure, and other development measures. Useful for constructing customized datasets and conducting international comparisons."
    },
    {
      "title": "Deutsche Bundesbank – National Accounts",
      "url_or_doi": "https://www.bundesbank.de/en/statistics/macroeconomic-accounting-systems/national-accounts",
      "justification": "Provides access to German macroeconomic statistics and historical national accounts time series. Relevant measures include GDP, income, expenditure, employment, and economic activity. The data can support research on Germany's economic development during 2010–2019, including changes in national output, investment patterns, and the relationships between different sectors of the economy."
    },
    {
      "title": "OECD Economic Surveys: Germany – Historical Statistical Series",
      "url_or_doi": "https://doi.org/10.1787/19990251",
      "justification": "The OECD's Germany economic survey series includes editions published in 2010, 2012, 2014, 2016, and 2018. These publications contain statistical tables and charts documenting economic performance, employment, productivity, public finances, and structural reforms. Although this is a publication series rather than a standalone downloadable dataset, its historical statistics provide useful evidence for studying German economic institutions and development throughout the 2010s."
    },
    {
      "title": "Eurostat and Destatis – German Quarterly GDP and Sectoral Economic Output",
      "url_or_doi": "https://data.europa.eu/data/datasets/https%3A-genesis.destatis.de-genesisws-downloads-00-tables-81000-0002_00?locale=en",
      "justification": "This European data portal entry provides access to German national accounts data originating from Destatis. It includes quarterly observations on GDP and gross value added, making it useful for investigating economic structure and sectoral development between 2010 and 2019. Researchers can use the data to study shifts in economic activity and assess Germany's economic performance over the decade."
    },
    {
      "title": "World Bank – Germany Economic and Development Time Series",
      "url_or_doi": "https://databank.worldbank.org/id/f06fb8ca",
      "justification": "A World Development Indicators DataBank view containing historical economic statistics, including observations for Germany. It can be used to examine GDP per capita and other development measures across multiple decades, including the 2010s. Particularly relevant for investigating long-term economic convergence, changes in prosperity, and Germany's position within the international economic system."
    }
  ]
}
